CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id TEXT NOT NULL,event_type TEXT NOT NULL,invite_id TEXT,source TEXT,payload TEXT,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_events_type ON events(event_type);CREATE INDEX IF NOT EXISTS idx_events_created ON events(created_at);CREATE TABLE IF NOT EXISTS unlocks(id INTEGER PRIMARY KEY AUTOINCREMENT,inviter_id TEXT NOT NULL,completed_session_id TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_unlocks_inviter ON unlocks(inviter_id);
